const phone = String($json.phone || '').replace(/[^\d+]/g, '');
if (!/^\+?\d{10,15}$/.test(phone)) throw new Error('Некорректный телефон');
const form = {
  name: String($json.name || '').trim(), phone, car: String($json.car || '').trim(),
  problem: String($json.problem || '').trim(),
  desired_time: [String($json.desired_date || '').trim(), String($json.desired_time || '').trim()].filter(Boolean).join(' '),
};
return [{ json: {
  source: 'form', client_chat_id: '', received_at: new Date().toISOString(), form_data: form,
  current_message: 'Новая заявка из формы: ' + JSON.stringify(form),
} }];

const input = $('Normalize Form').item.json;
const existing = $json && $json.id ? $json : {};
return [{ json: { ...input, existing_state: existing } }];

const context = $('Prepare Form Context').item.json;
const existing = context.existing_state || {};
const form = context.form_data || {};
const candidate = $json.output ?? $json.text ?? '';
let parsed = {};
let aiOk = true;
try {
  if (candidate && typeof candidate === 'object') {
    parsed = candidate;
  } else {
    let raw = String(candidate).replace(/\x60\x60\x60json/gi, '').replace(/\x60\x60\x60/g, '').trim();
    const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
    if (start >= 0 && end > start) raw = raw.slice(start, end + 1);
    parsed = JSON.parse(raw);
    if (typeof parsed === 'string') parsed = JSON.parse(parsed);
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('AI output is not an object');
} catch { aiOk = false; parsed = {}; }

const present = (value) => value !== undefined && value !== null && String(value).trim() !== '';
const value = (key, fallback = '') => String([parsed[key], existing[key], form[key], fallback].find(present) ?? '').trim();
const name = value('name');
const car = value('car');
const problem = value('problem');
let phoneDigits = value('phone').replace(/\D/g, '');
if (phoneDigits.length === 11 && phoneDigits.startsWith('8')) phoneDigits = '7' + phoneDigits.slice(1);
const phone = phoneDigits ? '+' + phoneDigits : '';
const phoneValid = /^\+\d{10,15}$/.test(phone);
const danger = /(тормоз|рул|дым|топлив|бензин|перегрев|кипит|не управ)/i.test(problem);
const desired = value('desired_time');
const desiredDate = desired ? new Date(desired) : null;
const validDate = Boolean(desiredDate && !Number.isNaN(desiredDate.getTime()) && desiredDate.getTime() > Date.now());
const complete = Boolean(name && phoneValid && car && problem && validDate);
const needsHuman = !aiOk || danger || Boolean(parsed.needs_human);
const ready = aiOk && complete && !needsHuman;

const service = /бампер|кузов|вмят|царап|крыл|двер|покрас|стекл/i.test(problem) ? 'Кузовной ремонт'
  : /масл|фильтр|техобслуж|\bто\b/i.test(problem) ? 'Техническое обслуживание'
  : /шин|колес|резин/i.test(problem) ? 'Шиномонтаж'
  : /аккум|электр|стартер|генератор/i.test(problem) ? 'Автоэлектрика'
  : 'Диагностика';

let reply = 'Данные получил. Передаю заявку администратору для проверки времени.';
if (!aiOk) reply = 'Не смог обработать сообщение автоматически. Я сохранил заявку и передал её администратору.';
else if (danger) reply = 'Ситуация может быть небезопасной. Не продолжайте движение, если управление или торможение нарушено. Я передал заявку администратору.';
else if (!name) reply = 'Как вас зовут?';
else if (!phoneValid) reply = 'Укажите номер телефона полностью: 10–15 цифр, например +79990000000.';
else if (!car) reply = 'Укажите марку, модель и год автомобиля.';
else if (!problem) reply = 'Коротко опишите проблему или нужную работу.';
else if (!validDate) reply = 'Укажите желаемые дату и время визита.';

const requestedDuration = Number(parsed.duration_minutes || existing.duration_minutes || 60);
return [{ json: {
  name, phone, car, problem, desired_time: desired,
  status: ready ? 'Ожидает подтверждения' : (needsHuman ? 'Нужен человек' : 'Сбор данных'),
  source: context.source, client_chat_id: String(context.client_chat_id || existing.client_chat_id || ''),
  service, urgency: danger ? 'critical' : value('urgency', 'normal'),
  ai_summary: aiOk ? value('ai_summary', problem) : 'ИИ недоступен — требуется ручная обработка.',
  proposed_start: value('proposed_start'), proposed_end: value('proposed_end'), alternatives_json: value('alternatives_json', '[]'),
  first_response_at: value('first_response_at', new Date().toISOString()), last_contact_at: new Date().toISOString(),
  appointment_event_id: value('appointment_event_id'), booked_at: value('booked_at'), failure_reason: aiOk ? '' : 'AI_PARSE_OR_API_FAILURE',
  reminder_24h_sent: value('reminder_24h_sent', 'false'), reminder_2h_sent: value('reminder_2h_sent', 'false'),
  sla_alert_sent: value('sla_alert_sent', 'false'), reply, ready_for_review: ready, needs_human: needsHuman,
  duration_minutes: Math.min(180, Math.max(30, Number.isFinite(requestedDuration) ? requestedDuration : 60)), ai_ok: aiOk,
} }];

const q = $json.callback_query;
if (q) {
  const [action, leadId] = String(q.data || '').split(':', 2);
  return [{ json: { kind: 'callback', action, lead_id: leadId, callback_query_id: q.id, actor_chat_id: String(q.message?.chat?.id || ''), callback_message_id: q.message?.message_id } }];
}
const m = $json.message || {};
const text = String(m.text || '').trim();
if (!text || !m.chat?.id) return [];
return [{ json: { kind: 'message', source: 'telegram', client_chat_id: String(m.chat.id), current_message: text, received_at: new Date().toISOString(), telegram_username: String(m.from?.username || ''), sender_name: [m.from?.first_name, m.from?.last_name].filter(Boolean).join(' ') } }];

const context = $('Prepare Telegram Context').item.json;
const existing = context.existing_state || {};
const form = context.form_data || {};
const candidate = $json.output ?? $json.text ?? '';
let parsed = {};
let aiOk = true;
try {
  if (candidate && typeof candidate === 'object') {
    parsed = candidate;
  } else {
    let raw = String(candidate).replace(/\x60\x60\x60json/gi, '').replace(/\x60\x60\x60/g, '').trim();
    const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
    if (start >= 0 && end > start) raw = raw.slice(start, end + 1);
    parsed = JSON.parse(raw);
    if (typeof parsed === 'string') parsed = JSON.parse(parsed);
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('AI output is not an object');
} catch { aiOk = false; parsed = {}; }

const present = (value) => value !== undefined && value !== null && String(value).trim() !== '';
const value = (key, fallback = '') => String([parsed[key], existing[key], form[key], fallback].find(present) ?? '').trim();
const name = value('name');
const car = value('car');
const problem = value('problem');
let phoneDigits = value('phone').replace(/\D/g, '');
if (phoneDigits.length === 11 && phoneDigits.startsWith('8')) phoneDigits = '7' + phoneDigits.slice(1);
const phone = phoneDigits ? '+' + phoneDigits : '';
const phoneValid = /^\+\d{10,15}$/.test(phone);
const danger = /(тормоз|рул|дым|топлив|бензин|перегрев|кипит|не управ)/i.test(problem);
const desired = value('desired_time');
const desiredDate = desired ? new Date(desired) : null;
const validDate = Boolean(desiredDate && !Number.isNaN(desiredDate.getTime()) && desiredDate.getTime() > Date.now());
const complete = Boolean(name && phoneValid && car && problem && validDate);
const needsHuman = !aiOk || danger || Boolean(parsed.needs_human);
const ready = aiOk && complete && !needsHuman;

const service = /бампер|кузов|вмят|царап|крыл|двер|покрас|стекл/i.test(problem) ? 'Кузовной ремонт'
  : /масл|фильтр|техобслуж|\bто\b/i.test(problem) ? 'Техническое обслуживание'
  : /шин|колес|резин/i.test(problem) ? 'Шиномонтаж'
  : /аккум|электр|стартер|генератор/i.test(problem) ? 'Автоэлектрика'
  : 'Диагностика';

const firstName = name.split(/\s+/)[0] || '';
let reply = firstName ? `Отлично, ${firstName}! Я собрала заявку и проверяю свободное время. После проверки сразу напишу вам.` : 'Данные получила. Проверяю свободное время.';
if (!aiOk) reply = 'Извините, сейчас не получилось обработать сообщение автоматически. Я сохранила заявку и передала её администратору — он поможет вам лично.';
else if (danger) reply = 'Похоже, ситуация может быть небезопасной. Пожалуйста, не продолжайте движение, если нарушены управление или торможение. Я уже передала заявку администратору.';
else if (!name) reply = 'Здравствуйте! Я Анна, виртуальный администратор Vektor Auto 😊 Помогу оформить запись. Как я могу к вам обращаться?';
else if (!phoneValid) reply = `${firstName}, приятно познакомиться! Оставьте, пожалуйста, номер телефона для связи — например, +7 999 000-00-00.`;
else if (!car) reply = 'Спасибо! Подскажите, пожалуйста, марку, модель и год автомобиля.';
else if (!problem) reply = 'Поняла 👍 Расскажите, пожалуйста, что случилось с автомобилем или какие работы нужны.';
else if (!validDate) reply = 'Хорошо! На какой день и время вам было бы удобно приехать? Можно написать, например: «завтра в 11:00».';

const requestedDuration = Number(parsed.duration_minutes || existing.duration_minutes || 60);
return [{ json: {
  name, phone, car, problem, desired_time: desired,
  status: ready ? 'Ожидает подтверждения' : (needsHuman ? 'Нужен человек' : 'Сбор данных'),
  source: context.source, client_chat_id: String(context.client_chat_id || existing.client_chat_id || ''),
  service, urgency: danger ? 'critical' : value('urgency', 'normal'),
  ai_summary: aiOk ? value('ai_summary', problem) : 'ИИ недоступен — требуется ручная обработка.',
  proposed_start: value('proposed_start'), proposed_end: value('proposed_end'), alternatives_json: value('alternatives_json', '[]'),
  first_response_at: value('first_response_at', new Date().toISOString()), last_contact_at: new Date().toISOString(),
  appointment_event_id: value('appointment_event_id'), booked_at: value('booked_at'), failure_reason: aiOk ? '' : 'AI_PARSE_OR_API_FAILURE',
  reminder_24h_sent: value('reminder_24h_sent', 'false'), reminder_2h_sent: value('reminder_2h_sent', 'false'),
  sla_alert_sent: value('sla_alert_sent', 'false'), reply, ready_for_review: ready, needs_human: needsHuman,
  duration_minutes: Math.min(180, Math.max(30, Number.isFinite(requestedDuration) ? requestedDuration : 60)), ai_ok: aiOk,
} }];

const lead = $('If Ready for Review').first().json;
const events = $input.all().map(i => i.json).filter(e => e && (e.id || e.start));
const duration = Math.min(180, Math.max(30, Number(lead.duration_minutes || 60))) * 60000;
const requested = new Date(lead.desired_time);
if (Number.isNaN(requested.getTime())) throw new Error('Некорректное желаемое время');
const busy = events.map(e => {
  const s = new Date(e.start?.dateTime || e.start || e.startTime || e.start?.date);
  const en = new Date(e.end?.dateTime || e.end || e.endTime || e.end?.date);
  return [s.getTime(), en.getTime()];
}).filter(([s, e]) => Number.isFinite(s) && Number.isFinite(e));
const slots = [];
let cursor = new Date(Math.max(requested.getTime(), Date.now() + 30 * 60000));
cursor.setMinutes(Math.ceil(cursor.getMinutes() / 30) * 30, 0, 0);
for (let i = 0; i < 7 * 48 && slots.length < 3; i++, cursor = new Date(cursor.getTime() + 30 * 60000)) {
  const local = DateTime.fromJSDate(cursor).setZone('Asia/Yakutsk');
  const weekday = local.weekday;
  const minutes = local.hour * 60 + local.minute;
  if (weekday === 7 || minutes < 540 || minutes + duration / 60000 > 1140) continue;
  const start = cursor.getTime(), end = start + duration;
  if (busy.some(([bs, be]) => start < be && end > bs)) continue;
  slots.push({ start: new Date(start).toISOString(), end: new Date(end).toISOString() });
}
if (!slots.length) throw new Error('Нет свободного окна в ближайшие 7 дней');
return [{ json: { ...lead, proposed_start: slots[0].start, proposed_end: slots[0].end, alternatives_json: JSON.stringify(slots.slice(1)), slot_changed: Math.abs(new Date(slots[0].start).getTime() - requested.getTime()) > 60000 } }];

const now = Date.now(); const due = [];
for (const item of $input.all()) {
  const j = item.json || {}; const start = new Date(j.proposed_start).getTime();
  if (!Number.isFinite(start) || !j.client_chat_id) continue;
  const minutes = (start - now) / 60000;
  let type = '';
  if (j.reminder_24h_sent !== 'true' && minutes >= 1380 && minutes <= 1500) type = '24h';
  if (j.reminder_2h_sent !== 'true' && minutes >= 105 && minutes <= 135) type = '2h';
  if (!type) continue;
  due.push({ json: { ...j, reminder_type: type, reminder_text: '⏰ Напоминание Vektor Auto\n\nЗапись ' + DateTime.fromISO(j.proposed_start).setZone('Asia/Yakutsk').toFormat('dd.LL.yyyy HH:mm') + '\n' + j.car + ' — ' + j.service } });
}
return due;

const now = Date.now(); return $input.all().filter(i => {
  const j = i.json || {}; const created = new Date(j.createdAt || j.first_response_at).getTime();
  return j.id && j.sla_alert_sent !== 'true' && Number.isFinite(created) && now - created >= 15 * 60000;
}).map(i => ({ json: { ...i.json, alert_text: '🚨 Заявка №' + i.json.id + ' ждёт подтверждения больше 15 минут\n' + (i.json.name || '') + ' · ' + (i.json.phone || '') } }));

const now = DateTime.now().setZone('Asia/Yakutsk'); const rows = $input.all().map(i => i.json || {}).filter(j => j.id);
const today = rows.filter(j => { const d = DateTime.fromISO(j.createdAt || j.first_response_at || '', { zone: 'Asia/Yakutsk' }); return d.isValid && d.hasSame(now, 'day'); });
const count = status => today.filter(j => j.status === status).length;
const responseSeconds = today.map(j => (new Date(j.first_response_at) - new Date(j.createdAt)) / 1000).filter(Number.isFinite);
const avg = responseSeconds.length ? Math.round(responseSeconds.reduce((a,b)=>a+b,0)/responseSeconds.length) : 0;
return [{ json: { report: '📊 Vektor Auto — отчёт за ' + now.toFormat('dd.LL.yyyy') + '

Новые заявки: ' + today.length + '
Записано: ' + count('Записан') + '
Ждут подтверждения: ' + count('Ожидает подтверждения') + '
Нужен человек: ' + count('Нужен человек') + '
Отказ: ' + count('Отказ') + '
Среднее время первого ответа: ' + avg + ' сек.' } }];
